/**
 * Stub of `@deepseek-ai/dsh-compaction-basic` for the replay harness.
 *
 * This stub is the **host**: it plays exactly the parties the installed DSH and
 * the failed session recorded. Every rule below is copied from source that was
 * read, not invented:
 *
 *  1. the summarizer is an adapter-backed model request whose payload is measured
 *     with the adapter's own accounting (`adapterTokensPerByte`); a request that
 *     does not fit the window is rejected with the recorded
 *     `pi-ai detected context overflow for model "…"`.
 *     Its **return shape** is the installed one —
 *     `dsh-compaction-basic/lib/index.js:329-337` answers
 *     `{ summary, rawOutput, llmStreamCall, provider, model, maxTokens, usage }`
 *     and carries **no `blocks` key** — because that shape is itself one of the
 *     defects under test (`docs/surface-contract.md` §0.2.1).
 *  2. a surface replacement may not cover node 0 (the system prompt). The contract
 *     (`dsh-session/lib/types/surface.js:388-390`) allows exactly one exception:
 *     a `system/message` event over exactly that one node. Anything else is
 *     rejected with the recorded
 *     `surface replace: node 0 holds the system prompt …`.
 *
 * `config.__replay` carries the harness-supplied host model; every call the
 * engine delegates lands in `host.log`, which is what the property assertions
 * read.
 */

import { ManualCompactionError } from "@deepseek-ai/dsh-compaction";

export class BasicCompactionEngine {
  static inject = ["llm", "tokenMeter", "sessions"];

  constructor(ctx, config = {}) {
    this.ctx = ctx;
    this.config = config;
    this.host = config?.__replay ?? {};
    const log = this.host.log ?? (this.host.log = { summarize: [], compactIfNeeded: [], compactRegion: [], compactNow: [], commits: [] });
    this.calls = log;
    this.calls.summarize ??= [];
    this.calls.compactIfNeeded ??= [];
    this.calls.compactRegion ??= [];
    this.calls.compactNow ??= [];
    this.calls.commits ??= [];
  }

  /** Reject whatever the adapter's own accounting says does not fit. */
  _request(messages) {
    const account = typeof this.host.adapterTokens === "function"
      ? this.host.adapterTokens
      : (list) => (Array.isArray(list) ? list : []).reduce((total, message) => total + Math.ceil(Buffer.byteLength(JSON.stringify(message ?? null), "utf8") * (this.host.adapterTokensPerByte ?? 0.34)), 0);
    const adapter = account(messages) + (this.host.headerTokens ?? 0);
    const budget = (this.host.window ?? 0) - (this.host.maxOutput ?? 0) - (this.host.margin ?? 0);
    const record = { messages: messages?.length ?? 0, adapter, budget };
    this.calls.summarize.push(record);
    if (adapter > budget) {
      this.calls.overflow = (this.calls.overflow ?? 0) + 1;
      const error = new Error(this.host.overflowMessage ?? "pi-ai detected context overflow");
      error.code = "INVALID_REQUEST";
      error.__overflow = true;
      throw error;
    }
    return record;
  }

  /**
   * The summarizer: one adapter-backed request, answering the installed shape.
   *
   * Note the absence of `blocks`: `dsh-compaction-basic/lib/index.js:329-337`
   * returns the text blocks under `summary`. A caller that only looks at
   * `blocks` therefore reads nothing at all — the defect recorded in
   * `docs/surface-contract.md` §0.2.1.
   */
  async summarize(input, agent, signal) {
    const record = this._request(Array.isArray(input?.messages) ? input.messages : []);
    const text = "x".repeat(this.host.summaryChars ?? 64);
    return {
      summary: [{ type: "text", text }],
      rawOutput: [{ type: "text", text }],
      llmStreamCall: true,
      provider: this.host.provider ?? "huaiyuan",
      model: this.host.model ?? "DeepSeek-V4.1-Flash",
      maxTokens: this.host.maxOutput,
      usage: { inputTokens: record.adapter, outputTokens: 8, totalTokens: record.adapter + 8 },
    };
  }

  /**
   * The host's surface rule (`dsh-session/lib/types/surface.js:388-390`).
   *
   * A range covering node 0 is refused unless it is a `system/message` over
   * exactly that one node. Returns the commit record, or throws the rejection.
   */
  _write(session, start, end, op = "replace") {
    const nodes = Array.isArray(session?.surface?.nodes) ? session.surface.nodes : [];
    const systemSeq = this.host.systemSeq ?? nodes[0];
    const coversNode0 = start <= systemSeq && systemSeq <= end;
    const viaContract = op === "system/message" && start === end && start === systemSeq;
    if (coversNode0 && viaContract === false) {
      this.calls.rejections = (this.calls.rejections ?? 0) + 1;
      const error = new Error(this.host.node0Message ?? "surface replace: node 0 holds the system prompt");
      error.__node0 = true;
      throw error;
    }
    session.surface.replaceGeneration += 1;
    const commit = { start, end, op, coversNode0, tokens: Math.max(0, end - start) };
    this.calls.commits.push(commit);
    return {
      shadowedRange: { start, end },
      shadowedSeqs: start === end ? [start] : [start, end],
      shadowedTokenCount: commit.tokens,
    };
  }

  /** The shipped replacement entry point. */
  async compactRegion(start, end, agent, signal, options) {
    const op = options?.event ?? "replace";
    this.calls.compactRegion.push({ start, end, op });
    if (this.host.throwingRegion === true) throw new Error("compactRegion exploded");
    return this._write(agent?.session, start, end, op);
  }

  /**
   * The shipped automatic path: summarize the old region, then replace it.
   *
   * On an oversized surface the summary request is the first thing to run, so it
   * is the first thing to fail — exactly the `pi-ai detected context overflow`
   * half of the recorded alternation.
   */
  async compactIfNeeded(agent, trigger, signal) {
    const session = agent?.session;
    const nodes = Array.isArray(session?.surface?.nodes) ? session.surface.nodes : [];
    const region = nodes.slice(0, Math.max(0, nodes.length - 1));
    this.calls.compactIfNeeded.push({ trigger, count: region.length });
    if (this.host.throwingBase === true) throw new Error("shipped path exploded");
    // The prompt the shipped path would send: every surface node serialized, so the
    // payload size tracks the real surface instead of a hand-picked constant.
    const messages = region.map((seq) => ({
      role: seq === this.host.systemSeq ? "system" : "user",
      content: [{ type: "text", text: JSON.stringify(session?.eventAt?.(seq)?.data ?? {}) }],
    }));
    await this.summarize({ messages }, agent, signal);
    if (region.length === 0) return null;
    return this._write(session, region[0], region[region.length - 1], "replace");
  }

  async compactNow(agent, signal, sourceCommandId) {
    this.calls.compactNow.push({ sourceCommandId });
    if (this.host.throwingManual === true) {
      throw new ManualCompactionError("busy", "manual compaction requires an idle agent with no waking queued work");
    }
    return { via: "now" };
  }
}

export default { BasicCompactionEngine };
